import unittest

from solution import decode_query


class DecodeQueryTests(unittest.TestCase):
    def test_empty_get_body_ignores_content_type(self):
        for content_type in ("", "text/plain", "application/xml", "nonsense"):
            for body in ("", "   ", "\t\r\n"):
                with self.subTest(content_type=content_type, body=body):
                    self.assertEqual(decode_query("GET", content_type, body), (200, {}))

    def test_json_media_type_parameters_case_and_deep_copy(self):
        status, value = decode_query(
            "GET", "  Application/JSON ; charset=utf-8", '{"a": [1, {"b": 2}]}'
        )
        self.assertEqual(status, 200)
        self.assertEqual(value, {"a": [1, {"b": 2}]})
        value["a"][1]["b"] = 99
        status2, value2 = decode_query(
            "GET", "application/json", '{"a": [1, {"b": 2}]}'
        )
        self.assertEqual((status2, value2), (200, {"a": [1, {"b": 2}]}))

    def test_non_get_precedes_body_and_content_checks(self):
        for method in ("POST", "get", " GET"):
            with self.subTest(method=method):
                self.assertEqual(decode_query(method, "application/json", "{"), (405, None))

    def test_nonempty_body_requires_json_content_type(self):
        for content_type in ("", "text/plain", "application/jsonish"):
            with self.subTest(content_type=content_type):
                self.assertEqual(decode_query("GET", content_type, "{}"), (415, None))

    def test_malformed_and_non_dictionary_json(self):
        for body in ("{", "null", "[]", '"text"', "3", "true"):
            with self.subTest(body=body):
                self.assertEqual(decode_query("GET", "application/json", body), (400, None))

    def test_argument_types(self):
        for args in ((None, "", ""), ("GET", None, ""), ("GET", "", b"")):
            with self.subTest(args=args):
                with self.assertRaises(TypeError):
                    decode_query(*args)


if __name__ == "__main__":
    unittest.main()

